function localTalentIcon(url){if(!url)return'';try{const parts=decodeURIComponent(new URL(url,location.href).pathname).split('/'),revision=parts.indexOf('revision'),filename=parts[revision>0?revision-1:parts.length-1].replace(/[\s_]+/g,'_');return `assets/talent-icons/${encodeURIComponent(filename)}`}catch{return url}}
