function talentInfo(name,c=data?.character){const talent=(data?.talentLibrary||[]).find(t=>t.name===name);if(!talent)return null;const owned=new Set((c?.talents||[]).map(x=>x.name)),automatic=Number(talent.automatic_level||0),has=owned.has(talent.name)||(automatic>0&&c.level>=automatic),spent=(c?.talents||[]).filter(x=>x.tree_name===talent.tree||x.tree===talent.tree).length,needed=Math.max(0,Number(talent.tier||0)-spent);return {talent,automatic,has,spent,needed,canBuy:!has&&!automatic&&needed===0&&Number(c?.talent_points||0)>0}}
function talentSelection(name,c){const s=talentInfo(name,c);if(!s)return '<section id="talent-selection" class="talent-selection"><p>Выберите талант в одном из деревьев.</p></section>';const t=s.talent,requirement=s.has?'Талант изучен':s.automatic?`Открывается автоматически на ${s.automatic} уровне`:s.needed?`Нужно ещё вложить в ветку: ${s.needed}`:'Доступен для изучения';return `<section id="talent-selection" class="talent-selection">${talentIcon(t,'large')}<div><small>${esc(t.tree)} · ступень ${t.tier}</small><h2>${esc(t.name)}</h2><b class="talent-requirement ${s.canBuy?'ready':''}">${esc(requirement)}</b><p>${esc(t.description)}</p></div><div class="talent-actions"><button class="talent-more" data-talent-details="${esc(t.name)}">ПОДРОБНОСТИ</button>${s.canBuy?`<button class="action" data-talent="${esc(t.name)}">ИЗУЧИТЬ</button>`:''}</div></section>`}
function renderTalents(p,c){const trees={};(data?.talentLibrary||[]).forEach(t=>(trees[t.tree]??=[]).push(t));const entries=Object.entries(trees);if(!entries.length){p.innerHTML='<section class="box"><p>Справочник талантов временно недоступен. Ваше личное дело продолжает работать.</p></section>';return}if(!entries.some(([,ts])=>ts.some(t=>t.name===selectedTalentName)))selectedTalentName=entries[0][1][0]?.name||'';p.innerHTML=`<div class="talent-heading"><p>Свободные очки талантов: <b>${c.talent_points??0}</b><small>Базовые деревья Вершителя и личные ветки предыстории используют общий запас.</small></p></div><div class="talent-carousel"><button class="talent-arrow prev" data-scroll-talents="-1" aria-label="Предыдущие ветки">‹</button><div class="talent-track">${entries.map(([tree,ts])=>{const spent=(c.talents||[]).filter(x=>x.tree_name===tree||x.tree===tree).length,tiers=[...new Set(ts.map(t=>Number(t.tier||0)))].sort((a,b)=>a-b);return `<section class="talent-tree"><header><h2>${esc(tree)}</h2><b>${spent}</b></header><div class="talent-lanes">${tiers.map(tier=>`<div class="talent-tier"><span>${tier}</span><div>${ts.filter(t=>Number(t.tier||0)===tier).map(t=>{const s=talentInfo(t.name,c),state=s.has?'owned':s.canBuy?'available':'locked';return `<button class="talent-node ${state} ${t.name===selectedTalentName?'selected':''}" data-select-talent="${esc(t.name)}" title="${esc(t.name)}">${talentIcon(t)}</button>`}).join('')}</div></div>`).join('')}</div></section>`}).join('')}</div><button class="talent-arrow next" data-scroll-talents="1" aria-label="Следующие ветки">›</button></div>${talentSelection(selectedTalentName,c)}`}
function selectTalent(name){selectedTalentName=name;document.querySelectorAll('.talent-node').forEach(n=>n.classList.toggle('selected',n.dataset.selectTalent===name));const old=$('#talent-selection');if(old)old.outerHTML=talentSelection(name,data.character)}
function openTalentDetails(name){const s=talentInfo(name),t=s?.talent;if(!t)return;const requirement=s.has?'Изучен':s.automatic?`Автоматически открывается на ${s.automatic} уровне`:`Требуется ${t.tier} очк. в ветке; вложено ${s.spent}`;$('#talent-dialog-body').innerHTML=`<div class="talent-dialog-head">${talentIcon(t,'large')}<div><small>${esc(t.tree)}</small><h2>${esc(t.name)}</h2></div></div><div class="talent-divider"></div><p class="talent-dialog-requirement">ТРЕБОВАНИЯ: <b>${esc(requirement)}</b></p><p class="talent-dialog-description">${esc(t.description)}</p>${t.source_url?`<a class="wiki-link" href="${esc(t.source_url)}" target="_blank" rel="noreferrer">ОТКРЫТЬ ИСТОЧНИК ↗</a>`:''}`;$('#talent-dialog').showModal()}
function renderFactions(p,c){const factions=new Set([...Object.keys(data.reputations),...data.factionTalents.map(t=>t.faction)]);p.innerHTML=`<div class="talent-trees">${[...factions].sort().map(name=>{const rep=data.reputations[name]||{favor:0,wrath:0},favorTier=Math.min(5,Math.floor(rep.favor/20)),wrathTier=Math.min(5,Math.floor(rep.wrath/20)),talents=data.factionTalents.filter(t=>t.faction===name);return `<section class="box"><h2>${esc(name)}</h2><div class="rep-axis"><b>Благосклонность ${rep.favor}/100 · ранг ${favorTier}</b><div class="meter"><i style="width:${rep.favor}%"></i></div></div><div class="rep-axis wrath"><b>Гнев ${rep.wrath}/100 · ранг ${wrathTier}</b><div class="meter"><i style="width:${rep.wrath}%"></i></div></div>${talents.map(t=>{const rank=t.axis==='favor'?favorTier:wrathTier,has=rank>=t.tier;return `<article class="talent ${has?'owned':''}">${talentIcon(t)}<div><b>${tip(t.name,t.description)}</b><p>${esc(t.description)}</p><small>${t.axis==='favor'?'Благосклонность':'Гнев'} · ранг ${t.tier}</small></div><b>${has?'✓':'🔒'}</b></article>`}).join('')||'<p>У этой стороны нет отдельных фракционных талантов.</p>'}</section>`}).join('')}</div>`}
