function selectedSpellSigils(){return [spellSigil(spellSelection.core),spellSigil(spellSelection.expression),...[...spellSelection.accents].map(spellSigil),spellSigil(spellSelection.enhancement)].filter(Boolean)}
function spellFormulaState(c){const core=spellSigil(spellSelection.core),expression=spellSigil(spellSelection.expression),accents=[...spellSelection.accents].map(spellSigil).filter(Boolean),enhancement=spellSigil(spellSelection.enhancement),lore=Number(c.skills?.['Знания']?.value||0);let error='';if(!core||!expression)error='Выберите ключ и выражение.';else if(expression.compatibleCores?.length&&!expression.compatibleCores.includes(core.name))error=`«${expression.name}» несовместимо с ключом «${core.name}».`;else if(enhancement?.compatibleCores?.length&&!enhancement.compatibleCores.includes(core.name))error=`«${enhancement.name}» несовместимо с этим ключом.`;else if(enhancement?.compatibleExpressions?.length&&!enhancement.compatibleExpressions.includes(expression.name))error=`«${enhancement.name}» несовместимо с этим выражением.`;const difficulty=Number(expression?.lore||0)+accents.reduce((n,s)=>n+Number(s.lore||0),0)+Number(enhancement?.lore||0);if(!error&&difficulty>lore)error=`Требуется Знаний: ${difficulty}; у персонажа: ${lore}.`;return {core,expression,accents,enhancement,difficulty,lore,error,ready:!!core&&!!expression&&!error}}
