function selectedAccent(family){return [...spellSelection.accents].map(spellSigil).find(s=>s?.family===family)}
function formulaName(state){return spellDraftName||data.spellNames?.[`${state.core?.name}|${state.expression?.name}`]||[state.core?.name,state.expression?.name].filter(Boolean).join(' · ')||'Новая формула'}
function percentFrom(items,word){const row=items.find(s=>s.family===word||s.name===word),m=row?.effect?.match(/([−-]?\d+)%/);return m?Math.abs(Number(m[1])):0}
function numberFrom(items,family){const row=items.find(s=>s.family===family),m=row?.effect?.match(/([+]?[0-9]+)/);return m?Number(m[1]):0}
function spellNumbers(state,c){const profile=expressionProfiles[state.expression?.name]||expressionProfiles['Сосредоточенное намерение'],skill=spellSkillByCore[state.core?.name]||'Знания',baseAccuracy=Number(c.skills?.[skill]?.value||0),wits=Number(c.attributes?.['Смекалка']||10),strength=percentFrom(state.accents,'Мощность'),recoveryCut=percentFrom(state.accents,'Циклические энергии'),accuracy=baseAccuracy+numberFrom(state.accents,'Точное действие'),enhancementPower=['Магия крови','Магия гордыни','Самоотверженная магия'].includes(state.enhancement?.name)?(state.enhancement.name==='Магия крови'?30:50):0,power=Math.max(1,Math.round((9+Math.floor(wits/2))*(1+(strength+enhancementPower)/100))),cooldown=Math.max(1,Math.ceil(profile.cooldown*(1-recoveryCut/100)*Number(data.derived?.cooldownMultiplier||1))),rangeBonus=numberFrom(state.accents,'Длинная хватка'),areaBonus=numberFrom(state.accents,'Безграничные пределы'),penetration=numberFrom(state.accents,'Пробивающая сила'),projectiles=profile.projectiles+numberFrom(state.accents,'Прыгающие заряды')+(state.enhancement?.name==='Залпы'?2:0);return {profile,skill,accuracy,power,cooldown,rangeBonus,areaBonus,penetration,projectiles}}
function isSigilCompatible(s,state){if(!s)return false;if(s.type==='expression'&&state.core&&s.compatibleCores?.length&&!s.compatibleCores.includes(state.core.name))return false;if(s.type==='enhancement'&&state.core&&s.compatibleCores?.length&&!s.compatibleCores.includes(state.core.name))return false;if(s.type==='enhancement'&&state.expression&&s.compatibleExpressions?.length&&!s.compatibleExpressions.includes(state.expression.name))return false;return true}
