function strokeSlot(family){const selected=selectedAccent(family),sample=(data.sigils.library||[]).find(s=>s.type==='accent'&&s.family===family);return `<button class="stroke-slot ${selected?'filled':''}" data-open-sigil-picker="accent|${esc(family)}" title="${esc(family)}${selected?`: ${selected.effect}`:''}">${sigilIcon(selected||sample,'stroke')}${selected?.tier?`<i>${['','I','II','III','IV','V'][selected.tier]}</i>`:''}</button>`}
