function sigilPicker(state){if(!spellPicker)return'';const [type,family]=spellPicker.split('|');let rows=(data.sigils.library||[]).filter(s=>s.type===type&&(type!=='accent'||s.family===family));const title=type==='core'?'Выберите сигил типа «Ключ»':type==='expression'?'Выберите сигил типа «Выражение»':type==='enhancement'?'Выберите сигил типа «Улучшение»':`Выберите уровень штриха «${family}»`;return `<section class="forge-picker"><header><b>${esc(title)}</b><button data-close-sigil-picker>×</button></header><div>${rows.map(s=>{const compatible=isSigilCompatible(s,state),locked=!s.known||!compatible,selected=s.key===spellSelection.core||s.key===spellSelection.expression||spellSelection.accents.has(s.key)||s.key===spellSelection.enhancement;return `<button class="picker-sigil ${selected?'selected':''} ${locked?'locked':''}" data-pick-sigil="${esc(s.key)}" title="${esc(!s.known?'Нужен свиток':!compatible?'Несовместимо с текущей формулой':`${s.name}: ${s.effect}`)}">${sigilIcon(s,'picker')}${s.tier?`<i>${['','I','II','III','IV','V'][s.tier]}</i>`:''}<span>${esc(s.name)}</span><small>${!s.known?'🔒':!compatible?'НЕЛЬЗЯ':s.lore?`${s.lore} ЗН.`:'ИЗУЧЕН'}</small></button>`}).join('')}</div></section>`}
