function spellPreview(state,c){if(!state.core||!state.expression)return `<section class="game-spell-readout empty"><div class="result-rune">◇</div><div><h3>Выберите ключ и выражение</h3><p>Ключ задаёт школу магии, выражение — форму, цель и способ применения.</p></div></section>`;const n=spellNumbers(state,c),support=['Жизнь','Рвение','Иллюзия'].includes(state.core.name)||['Охранная форма','Материальная сила'].includes(state.expression.name),effectLabel=support?'Сила эффекта':'Урон',extra=[...state.accents,...(state.enhancement?[state.enhancement]:[])],details=data.spellDetails?.[`${state.core.name}|${state.expression.name}`]||{};return `<section class="game-spell-readout ${state.error?'invalid':''}"><div class="result-rune">${sigilIcon(state.core,'result')}</div><div class="spell-copy"><header><h3>${esc(formulaName(state))}</h3><b class="knowledge-cost ${state.error?'over':''}">Знания: ${state.difficulty}</b></header><div class="spell-stat-lines"><span title="Число раундов до повторного применения. Быстрота и циклические энергии сокращают это время."><b>Перезарядка:</b> ${scaledRoundText(n.cooldown)}</span><span title="Максимальное расстояние до выбранной цели."><b>Дистанция:</b> ${esc(n.profile.range)}${n.rangeBonus?` + ${n.rangeBonus} м`:''}</span><span title="Число основных и дополнительных целей формулы."><b>Цели:</b> ${esc(n.profile.target)}${n.projectiles>1?` · ${n.projectiles} снаряда`:''}</span><span title="Размер зоны, задеваемой заклинанием."><b>Область действия:</b> ${esc(n.profile.area)}${n.areaBonus?` + ${n.areaBonus} м`:''}</span><span title="Итоговый диапазон до брони и сопротивлений цели."><b>${effectLabel}:</b> ${Math.max(1,n.power-4)}–${n.power+4}</span><span title="Навык школы плюс штрих точного действия сравниваются с указанной защитой цели."><b>Точность:</b> ${n.accuracy} против защиты «${esc(n.profile.defense)}»</span>${n.penetration?`<span title="На это значение уменьшается броня цели."><b>Пробивание брони:</b> ${n.penetration}</span>`:''}<span><b>Навыки боя:</b> ${esc(n.skill)} (${Number(c.skills?.[n.skill]?.value||0)}) и Знания (${state.lore})</span></div>${details.description?`<p class="spell-official-description">${esc(details.description)}</p>`:''}${extra.length?`<div class="spell-mod-list"><b>Штрихи заклинания:</b>${extra.map(s=>`<span>${esc(s.name)} — ${esc(s.effect)}</span>`).join('')}</div>`:''}<p>${esc(state.core.effect)} ${esc(state.expression.effect)}</p>${state.error?`<strong>${esc(state.error)}</strong>`:''}</div></section>`}
function learnedScrolls(){const scrolls=data.sigils.scrolls||[];if(!scrolls.length)return '<p class="empty-scrolls">В инвентаре нет неизученных свитков сигилов.</p>';return scrolls.map(row=>`<article class="sigil-scroll ${row.known?'known':''}">${sigilIcon(row.sigil)}<div><small>СВИТОК · ${row.quantity} ШТ.</small><b>${esc(row.sigil.name)}${row.sigil.tier?` ${['','I','II','III','IV','V'][row.sigil.tier]}`:''}</b><p>${esc(row.sigil.effect)}</p></div>${row.known?'<span>ИЗУЧЕН</span>':`<button class="action" data-learn-sigil="${row.inventoryId}">ИЗУЧИТЬ</button>`}</article>`).join('')}
function spellCoreIcon(spell,size='small'){return sigilIcon((data.sigils.library||[]).find(s=>s.type==='core'&&s.name===spell.core)||{name:spell.core},size)}
function grimoireIcon(spell,slot){if(!spell)return `<span class="grimoire-empty" title="Свободная ячейка">+</span>`;return `<button class="grimoire-icon ${Number(spell.id)===Number(editingSpellId)?'selected':''}" data-spell-load="${spell.id}" title="${esc(spell.name)} · ${spell.difficulty} Зн.">${spellCoreIcon(spell,'grimoire')}<i>${slot}</i></button>`}
function loadSpellToForge(spell){if(!spell)return;const core=sigilByName('core',spell.core),expression=sigilByName('expression',spell.expression);spellSelection={core:core?.key||'',expression:expression?.key||'',accents:new Set((spell.accents||[]).map(name=>sigilByName('accent',name)?.key).filter(Boolean)),enhancement:sigilByName('enhancement',(spell.enhancements||[])[0])?.key||''};editingSpellId=Number(spell.id);spellDraftName=spell.name;selectedSigilKey='';spellPicker=''}
function renderSpells(p,c){const state=spellFormulaState(c),limit=Number(data.equipmentLimits?.spellSlots||4),prepared=data.spells.filter(s=>s.equipped_slot!=null),bySlot=new Map(prepared.map(s=>[Number(s.equipped_slot),s])),reserve=data.spells.filter(s=>s.equipped_slot==null),editing=data.spells.find(s=>Number(s.id)===Number(editingSpellId));p.innerHTML=`<section class="tyranny-spell-screen"><div class="sigil-forge"><header class="forge-title"><h2>Сигилы заклинаний</h2><span>${editing?'РЕДАКТИРОВАНИЕ ФОРМУЛЫ':'НОВАЯ ФОРМУЛА'}</span></header><div class="forge-upper"><div class="forge-controls"><div class="primary-sigils">${forgeSlot('КЛЮЧИ','core',state.core)}${forgeSlot('ВЫРАЖЕНИЯ','expression',state.expression)}</div><b class="strokes-label">ШТРИХИ</b><div class="stroke-grid">${strokeFamilies.map(strokeSlot).join('')}${enhancementSlot()}</div>${sigilPicker(state)}</div><div class="assembled-rune">${state.core?sigilIcon(state.core,'assembled'):'<span>◇</span>'}<small>${state.expression?esc(state.expression.name):'Выберите выражение'}</small></div></div>${selectedSigilPanel()}${spellPreview(state,c)}<label class="spell-name-edit">Название заклинания<input id="spell-name" value="${esc(formulaName(state))}" maxlength="80" ${state.core&&state.expression?'':'disabled'}></label><footer class="forge-actions"><button class="sigil-reset">СБРОС</button><button id="save-spell" class="game-button" ${state.ready?'':'disabled'}>${editing?'СОХРАНИТЬ':'НАЗНАЧИТЬ'}</button>${editing?`<button class="game-button secondary" data-spell-equip="${editing.id}" data-equipped="${editing.equipped_slot==null?'1':'0'}">${editing.equipped_slot==null?'ПОДГОТОВИТЬ':'В РЕЗЕРВ'}</button><button class="game-button danger" data-spell-delete="${editing.id}">УДАЛИТЬ</button>`:''}</footer></div><aside class="party-grimoire"><header><h2>Заклинания персонажа</h2><div class="spell-capacity"><b>${prepared.length}/${limit}</b><small>ЯЧЕЕК</small></div></header><div class="caster-card">${c.portrait_url?`<img src="${esc(c.portrait_url)}" alt="">`:'<span>?</span>'}<div><b>${esc(c.name)}</b><small>Знания: ${state.lore}</small><div class="grimoire-grid">${Array.from({length:limit},(_,n)=>grimoireIcon(bySlot.get(n+1),n+1)).join('')}</div></div></div><section class="reserve-tray"><h3>Резерв</h3><p>Формулы в резерве нельзя применять в бою.</p><div>${reserve.map((s,n)=>grimoireIcon(s,`Р${n+1}`)).join('')||'<small>Резерв пуст.</small>'}</div></section>${editing?`<article class="selected-formula"><b>${esc(editing.name)}</b><span>${esc(editing.core)} · ${esc(editing.expression)}</span><small>${[...(editing.accents||[]),...(editing.enhancements||[])].map(esc).join(' · ')||'Без штрихов'}</small></article>`:'<p class="grimoire-help">Нажмите на руну, чтобы открыть формулу на столе.</p>'}</aside></section><section class="sigil-scroll-case box"><header><div><small>ИНВЕНТАРЬ ЗНАНИЙ</small><h2>Свитки сигилов</h2></div><p>Изучение расходует один свиток и навсегда открывает символ персонажу.</p></header><div class="sigil-scroll-list">${learnedScrolls()}</div></section>`}
function itemVisual(i){const letter=(i?.name||'?')[0]||'?';return `<span class="gear-art"><i>${esc(letter)}</i>${i?.image_url?`<img src="${esc(i.image_url)}" alt="" referrerpolicy="no-referrer" loading="lazy" onerror="this.remove()">`:''}</span>`}
function equipmentSlot(slot,label,position,bySlot){const item=bySlot[slot];return `<div class="paper-slot ${position}"><b>${esc(label)}</b><button ${item?`data-item-details="${item.inventory_id}"`:''} title="${esc(item?.name||slot)}">${item?itemVisual(item):'<span class="empty-rune">◇</span>'}</button></div>`}
function statIcon(file,label,value,help=''){return `<div class="combat-stat" title="${esc(help||label)}"><img src="assets/stat-icons/${file}" alt=""><span>${esc(label)}</span><b>${esc(value)}</b></div>`}
function compatibleSlots(i){const limits=data.equipmentLimits,slots=[];if(i.category==='Броня')return i.slot?[i.slot]:['Голова','Торс','Руки','Ноги'];if(i.category==='Аксессуары')return['Аксессуар 1','Аксессуар 2'];if(['Расходуемые предметы','Зелья','Еда'].includes(i.category))return Array.from({length:limits.quickSlots},(_,n)=>`Быстрый предмет ${n+1}`);if(['Одноручное оружие','Двуручное оружие','Парное оружие','Луки','Метательное оружие','Посохи','Щиты'].includes(i.category)){for(let n=1;n<=limits.weaponSets;n++){const r=['I','II','III','IV'][n-1];if(i.category!=='Щиты')slots.push(`Оружие ${r} — правая рука`);if(!Number(i.hands||0)||Number(i.hands)<2)slots.push(`Оружие ${r} — левая рука`)}return slots}return slots}
function inventoryItemCard(i){const slots=compatibleSlots(i);return `<article class="bag-item" data-item-details="${i.inventory_id}">${itemVisual(i)}<div><b>${esc(i.name)}</b><small>${esc(i.category)} · ${esc(i.quality)}</small></div>${slots.length?`<select class="equipment-select" data-equip="${i.inventory_id}"><option value="">Экипировать…</option>${slots.map(s=>`<option>${esc(s)}</option>`).join('')}</select>`:''}</article>`}
function renderInventory(p,c){
 const cap=data.capacity,d=data.derived,a=d.attack,limits=data.equipmentLimits;
 const bySlot=Object.fromEntries(data.inventory.filter(i=>i.equipped_slot).map(i=>[i.equipped_slot,i]));
 const roman=['I','II','III','IV'][d.activeWeaponSet-1]||'I';
 const quick=Array.from({length:limits.quickSlots},(_,n)=>equipmentSlot(`Быстрый предмет ${n+1}`,String(n+1),`quick q${n+1}`,bySlot)).join('');
 const weaponSets=Array.from({length:4},(_,n)=>{const r=['I','II','III','IV'][n],unlocked=n<limits.weaponSets,item=bySlot[`Оружие ${r} — правая рука`];return `<button class="weapon-set ${n+1===d.activeWeaponSet?'active':''}" data-weapon-set="${n+1}" ${unlocked?'':'disabled'}><b>${r}</b>${unlocked?(item?itemVisual(item):'<span>◇</span>'):'<span>🔒</span>'}</button>`}).join('');
 const stats=[
  statIcon('health.png','Здоровье',`${c.health}/${c.health_max}`,'Текущее и максимальное здоровье.'),
  statIcon('accuracy.png','Точность',a.accuracy,`Навык атаки: ${a.skill}. Учитывает активный комплект и экипировку.`),
  statIcon('critical.png','Крит. шанс',`${a.criticalChance}%`,'Вероятность критического результата.'),
  statIcon('recovery.png','Восстановление',roundText(a.recovery),'Задержка от активного оружия и надетой брони.'),
  statIcon('damage.png','Урон',`${a.damageMin}–${a.damageMax}`,'Урон активного оружейного комплекта с учётом Силы.'),
  '<h3>Защиты</h3>',statIcon('endurance.png','Выносливость',d.defenses['Выносливость']||0),statIcon('will.png','Воля',d.defenses['Воля']||0),statIcon('magic.png','Магия',d.defenses['Магия']||0),statIcon('parry.png','Парирование',d.defenses['Парирование']||0),statIcon('dodge.png','Уклонение',d.defenses['Уклонение']||0),
  '<h3>Броня</h3>',statIcon('armor.png','Поглощение',d.armor||0),statIcon('deflection.png','Отражение',`${d.deflection||0}%`)
 ].join('');
 const portrait=c.portrait_url?`<img class="paperdoll-character" src="${esc(c.portrait_url)}" alt="${esc(c.name)}">`:`<div class="paperdoll-silhouette">${esc(c.name[0]||'Ж')}</div>`;
 const slots=[equipmentSlot('Голова','Голова','head',bySlot),equipmentSlot('Торс','Торс','torso',bySlot),equipmentSlot('Аксессуар 1','Аксессуар','accessory-one',bySlot),equipmentSlot('Руки','Руки','hands',bySlot),equipmentSlot('Ноги','Ноги','feet',bySlot),equipmentSlot('Аксессуар 2','Аксессуар','accessory-two',bySlot),equipmentSlot(`Оружие ${roman} — правая рука`,'П. рука','weapon-main',bySlot),equipmentSlot(`Оружие ${roman} — левая рука`,'Л. рука','weapon-off',bySlot)].join('');
 const bagItems=data.inventory.filter(i=>!i.equipped_slot);
 p.innerHTML=`<div class="inventory-screen"><aside class="combat-sheet"><h2>Показатели</h2>${stats}</aside><section class="paperdoll"><div class="paperdoll-frame">${portrait}${slots}<div class="quick-title">Быстрый доступ</div><div class="quick-slots">${quick}</div></div><h3>Комплекты оружия</h3><div class="weapon-sets">${weaponSets}</div></section><aside class="bag"><header><div><h2>Инвентарь</h2><p>Занято ${cap.used} из ${cap.capacity} · Атлетика ${cap.athletics}</p></div><span>${bagItems.length}</span></header><div class="bag-scroll">${bagItems.map(inventoryItemCard).join('')||'<p class="empty-bag">Сумка пуста.</p>'}</div></aside></div>`;
}
function openItemDetails(id){const i=data.inventory.find(x=>Number(x.inventory_id)===Number(id));if(!i)return;const props=Object.entries(i.properties||{}).map(([k,v])=>`<li><span>${esc(k)}</span><b>${esc(v)}</b></li>`).join('');$('#item-dialog-body').innerHTML=`<div class="item-dialog-head">${itemVisual(i)}<div><small>${esc(i.category)} · ${esc(i.quality)}</small><h2>${esc(i.name)}</h2>${i.equipped_slot?`<b>${esc(i.equipped_slot)}</b>`:''}</div></div><h3>Описание</h3><p>${esc(i.description||'Описание отсутствует.')}</p><ul>${i.damage_max?`<li><span>Урон</span><b>${i.damage_min}–${i.damage_max}</b></li>`:''}${i.armor?`<li><span>Броня</span><b>${i.armor}</b></li>`:''}${i.recovery?`<li><span>Восстановление</span><b>${roundText(i.recovery)}</b></li>`:''}${props}</ul><h3>Предыстория</h3><p>${esc(i.lore||'Сведения о предыстории предмета не сохранились.')}</p><div class="item-dialog-actions">${i.equipped_slot?`<button class="action" data-unequip="${i.inventory_id}">СНЯТЬ</button>`:''}${i.source_url?`<a class="wiki-link" href="${esc(i.source_url)}" target="_blank" rel="noreferrer">ИСТОЧНИК ↗</a>`:''}</div>`;$('#item-dialog').showModal()}
async function mutate(path,body){try{const j=await request(`/api/portal/${encodeURIComponent(token)}/${path}`,{method:'POST',body:JSON.stringify(body)});data=normalize(j);toast(j.message);renderCabinet()}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{
 const v=e.target.closest('[data-view]');if(v)showView(v.dataset.view);
 const category=e.target.closest('[data-encyclopedia-category]');if(category){encyclopediaCategory=category.dataset.encyclopediaCategory;renderEncyclopedia()}
 const encyclopediaItem=e.target.closest('[data-encyclopedia-entry]');if(encyclopediaItem){encyclopediaSelected=encyclopediaItem.dataset.encyclopediaEntry;renderEncyclopedia()}
 const encyclopediaLink=e.target.closest('[data-encyclopedia-term]');if(encyclopediaLink)openEncyclopedia(encyclopediaLink.dataset.encyclopediaTerm);
 const encyclopediaTip=e.target.closest('[data-encyclopedia-tip]');if(encyclopediaTip)openEncyclopedia(encyclopediaTip.dataset.encyclopediaTip);
 const card=e.target.closest('[data-id]');if(card)openRecord(card.dataset.id);
 const tabBtn=e.target.closest('[data-tab]');if(tabBtn){tab=tabBtn.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b===tabBtn));renderTab()}
 const selected=e.target.closest('[data-select-talent]');if(selected)selectTalent(selected.dataset.selectTalent);
 const details=e.target.closest('[data-talent-details]');if(details)openTalentDetails(details.dataset.talentDetails);
 const item=e.target.closest('[data-item-details]');if(item&&!e.target.closest('select'))openItemDetails(item.dataset.itemDetails);
 const set=e.target.closest('[data-weapon-set]');if(set&&!set.disabled)mutate('weapon-set',{number:+set.dataset.weaponSet});
 const trainingAction=e.target.closest('[data-training-kind]');if(trainingAction&&!trainingAction.disabled&&!trainingAction.matches('[data-picker-action]'))trainingMutate('action',{kind:trainingAction.dataset.trainingKind,name:trainingAction.dataset.trainingName||''});
 const pickerAction=e.target.closest('[data-picker-action]');if(pickerAction&&!pickerAction.disabled){if(quickbarEditing){mutate('combat-quickbar',{slot:quickbarEditing,kind:pickerAction.dataset.actionKind,name:pickerAction.dataset.actionName});quickbarEditing=0;combatPicker=''}else trainingMutate('action',{kind:pickerAction.dataset.actionKind,name:pickerAction.dataset.actionName})}
 const quickSlot=e.target.closest('[data-quick-slot]');if(quickSlot&&!quickSlot.dataset.trainingKind){quickbarEditing=+quickSlot.dataset.quickSlot;combatPicker='ability';renderTraining($('#panel'),data.character)}
 const openCombatPicker=e.target.closest('[data-combat-picker]');if(openCombatPicker){combatPicker=combatPicker===openCombatPicker.dataset.combatPicker?'':openCombatPicker.dataset.combatPicker;quickbarEditing=0;renderTraining($('#panel'),data.character)}
 if(e.target.closest('[data-combat-picker-close]')){combatPicker='';quickbarEditing=0;renderTraining($('#panel'),data.character)}
 const stance=e.target.closest('[data-stance-name]');if(stance){combatPicker='';trainingMutate('action',{kind:'stance',name:stance.dataset.stanceName})}
 const targetToken=e.target.closest('[data-target-id]');if(targetToken&&!targetToken.disabled)trainingMutate('action',{kind:'select_target',targetId:targetToken.dataset.targetId});
 const moveCell=e.target.closest('[data-move-x]');if(moveCell&&!moveCell.disabled)trainingMutate('action',{kind:'move',x:+moveCell.dataset.moveX,y:+moveCell.dataset.moveY});
 const trainingSet=e.target.closest('[data-training-set]');if(trainingSet&&!trainingSet.disabled)trainingMutate('action',{kind:'weapon_set',number:+trainingSet.dataset.trainingSet});
 if(e.target.closest('.training-start'))trainingMutate('start');if(e.target.closest('.training-reset'))trainingMutate('reset');
 const scroll=e.target.closest('[data-scroll-talents]');if(scroll){const track=scroll.parentElement.querySelector('.talent-track');track?.scrollBy({left:Number(scroll.dataset.scrollTalents)*Math.max(340,track.clientWidth*.78),behavior:'smooth'})}
 const a=e.target.closest('[data-attr]');if(a)mutate('attribute',{name:a.dataset.attr});const t=e.target.closest('[data-talent]');if(t)mutate('talent',{name:t.dataset.talent});
 const u=e.target.closest('[data-unequip]');if(u){$('#item-dialog').close();mutate('equipment',{inventoryId:+u.dataset.unequip,unequip:true})}
 const openPicker=e.target.closest('[data-open-sigil-picker]');if(openPicker){spellPicker=spellPicker===openPicker.dataset.openSigilPicker?'':openPicker.dataset.openSigilPicker;selectedSigilKey='';renderSpells($('#panel'),data.character)}
 if(e.target.closest('[data-close-sigil-picker]')){spellPicker='';renderSpells($('#panel'),data.character)}
 const pickSigil=e.target.closest('[data-pick-sigil]');if(pickSigil){const s=spellSigil(pickSigil.dataset.pickSigil),state=spellFormulaState(data.character);if(s){selectedSigilKey=s.key;if(s.known&&isSigilCompatible(s,state)){if(s.type==='core'){const changed=spellSelection.core!==s.key;spellSelection.core=s.key;if(changed){spellSelection.accents=new Set();spellSelection.enhancement='';spellDraftName=''}const next=spellFormulaState(data.character);if(next.expression&&!isSigilCompatible(next.expression,next))spellSelection.expression=''}else if(s.type==='expression'){const changed=spellSelection.expression!==s.key;spellSelection.expression=s.key;if(changed){spellSelection.accents=new Set();spellSelection.enhancement='';spellDraftName=''}}else if(s.type==='enhancement')spellSelection.enhancement=spellSelection.enhancement===s.key?'':s.key;else{const wasSelected=spellSelection.accents.has(s.key);for(const key of [...spellSelection.accents])if(spellSigil(key)?.family===s.family)spellSelection.accents.delete(key);if(!wasSelected)spellSelection.accents.add(s.key)}spellPicker=''}}renderSpells($('#panel'),data.character)}
 const loadSpell=e.target.closest('[data-spell-load]');if(loadSpell){loadSpellToForge(data.spells.find(s=>Number(s.id)===Number(loadSpell.dataset.spellLoad)));renderSpells($('#panel'),data.character)}
 const learn=e.target.closest('[data-learn-sigil]');if(learn)mutate('sigil/learn',{inventoryId:+learn.dataset.learnSigil});
 const spellEquip=e.target.closest('[data-spell-equip]');if(spellEquip)mutate('spell/equip',{spellId:+spellEquip.dataset.spellEquip,equipped:spellEquip.dataset.equipped==='1'});
 const spellDelete=e.target.closest('[data-spell-delete]');if(spellDelete&&confirm('Удалить эту формулу из гримуара?'))mutate('spell/delete',{spellId:+spellDelete.dataset.spellDelete});
 if(e.target.closest('.sigil-reset')&&!e.target.closest('[data-spell-equip]')){spellSelection={core:'',expression:'',accents:new Set(),enhancement:''};selectedSigilKey='';spellDraftName='';spellPicker='';editingSpellId=0;renderSpells($('#panel'),data.character)}
 if(e.target.id==='save-spell'){const state=spellFormulaState(data.character);if(state.ready){spellDraftName=$('#spell-name').value;mutate('spell',{spellId:editingSpellId||undefined,name:spellDraftName,core:spellSelection.core,expression:spellSelection.expression,accents:[...spellSelection.accents],enhancements:spellSelection.enhancement?[spellSelection.enhancement]:[]});spellPicker=''}}
});
document.addEventListener('pointerover',e=>{const target=e.target.closest('[data-encyclopedia-tip]');if(!target)return;const entry=encyclopediaEntry(target.dataset.encyclopediaTip),popover=$('#encyclopedia-popover');if(!entry)return;popover.innerHTML=`<small>${esc(entry.categoryName)}</small><b>${esc(entry.title)}</b><p>${esc(glossaryPlain(entry.body))}</p><i>Нажмите, чтобы открыть статью</i>`;popover.hidden=false;const rect=target.getBoundingClientRect(),width=Math.min(390,innerWidth-24);popover.style.width=`${width}px`;let left=Math.min(innerWidth-width-12,Math.max(12,rect.left));let top=rect.bottom+9;if(top+popover.offsetHeight>innerHeight-12)top=Math.max(12,rect.top-popover.offsetHeight-9);popover.style.left=`${left}px`;popover.style.top=`${top}px`});
document.addEventListener('pointerout',e=>{const target=e.target.closest('[data-encyclopedia-tip]');if(target&&!target.contains(e.relatedTarget))$('#encyclopedia-popover').hidden=true});
document.addEventListener('pointerover',e=>{const action=e.target.closest('[data-effect-cells]');if(!action)return;document.querySelectorAll('.tactical-cell.effect-preview').forEach(cell=>cell.classList.remove('effect-preview'));for(const key of (action.dataset.effectCells||'').split(',').filter(Boolean))document.querySelector(`[data-cell="${CSS.escape(key)}"]`)?.classList.add('effect-preview')});
document.addEventListener('pointerover',e=>{const action=e.target.closest('[data-effect-cells]');if(!action)return;const map=document.querySelector('.tactical-map'),trajectory=map?.querySelector('.spell-trajectory');if(map)map.dataset.previewTargeting=action.dataset.targeting||'unit';if(trajectory)trajectory.classList.toggle('visible',['spell','ability','attack'].includes(action.dataset.actionKind||action.dataset.trainingKind))});
document.addEventListener('pointerout',e=>{const action=e.target.closest('[data-effect-cells]');if(action&&!action.contains(e.relatedTarget)){document.querySelectorAll('.tactical-cell.effect-preview').forEach(cell=>cell.classList.remove('effect-preview'));document.querySelector('.spell-trajectory')?.classList.remove('visible')}});
document.addEventListener('dragstart',e=>{const action=e.target.closest('[data-action-kind]');if(!action)return;e.dataTransfer.setData('application/json',JSON.stringify({kind:action.dataset.actionKind,name:action.dataset.actionName}));e.dataTransfer.effectAllowed='copy'});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-quick-slot]')){e.preventDefault();e.target.closest('[data-quick-slot]').classList.add('drop-ready')}});
document.addEventListener('dragleave',e=>e.target.closest('[data-quick-slot]')?.classList.remove('drop-ready'));
document.addEventListener('drop',e=>{const slot=e.target.closest('[data-quick-slot]');if(!slot)return;e.preventDefault();slot.classList.remove('drop-ready');try{const action=JSON.parse(e.dataTransfer.getData('application/json'));mutate('combat-quickbar',{slot:+slot.dataset.quickSlot,kind:action.kind,name:action.name})}catch{toast('Не удалось назначить действие.')}});
document.addEventListener('contextmenu',e=>{const slot=e.target.closest('[data-quick-slot]');if(!slot)return;e.preventDefault();mutate('combat-quickbar',{slot:+slot.dataset.quickSlot,kind:'',name:''})});
document.addEventListener('keydown',e=>{if(tab!=='training'||e.repeat||e.target.matches('input,textarea,select'))return;const n=Number(e.key);if(n>=1&&n<=5){const slot=document.querySelector(`[data-quick-slot="${n}"]`);if(slot&&!slot.disabled)slot.click()}if(e.key.toLowerCase()==='s')document.querySelector('[data-combat-picker="stance"]')?.click();if(e.key.toLowerCase()==='p')document.querySelector('[data-combat-picker="spell"]')?.click()});
document.addEventListener('change',e=>{if(e.target.matches('[data-equip]')&&e.target.value)mutate('equipment',{inventoryId:+e.target.dataset.equip,slot:e.target.value})});document.addEventListener('input',e=>{if(e.target.id==='spell-name')spellDraftName=e.target.value;if(e.target.id==='encyclopedia-search')renderEncyclopedia()});$('#search').addEventListener('input',renderArchive);$('#record .close').onclick=()=>$('#record').close();$('#talent-dialog .close').onclick=()=>$('#talent-dialog').close();$('#item-dialog .close').onclick=()=>$('#item-dialog').close();boot();
